	public void ScaleIngameUI(float scaleFactor)
	{
		if (scaleFactor < 0f)
		{
			scaleFactor = 0f;
		}
		else if (scaleFactor > 1f)
		{
			scaleFactor = 1f;
		}
		float num = Screen.width;
		float num2 = Screen.height;
		if (num <= 1366f || num2 <= 768f)
		{
			scaleFactor = 0f;
		}
		if (scaleFactor == 0f)
		{
			iUIScaleValueWidth = (int)num;
			iUIScaleValueHeight = (int)num2;
		}
		else
		{
			float num3 = 1360f;
			float num4 = 768f;
			float num5 = num / num3;
			float num6 = num2 / num4;
			float num7 = Mathf.Min(num5, num6);
			if (scaleFactor < 1f)
			{
				num7 = (num7 - 1f) * scaleFactor + 1f;
			}
			iUIScaleValueWidth = (int)(num / num7);
			iUIScaleValueHeight = (int)(num2 / num7);
		}
		UIScaleValueWidth = iUIScaleValueWidth.ToString();
		UIScaleValueHeight = iUIScaleValueHeight.ToString();
		if ((Object)(object)FatControler.instance != (Object)null)
		{
			FatControler.instance.SHLowerUIPoint = 0f;
		}
		if (Show_InGame)
		{
			Director.instance.ReGetUIEdge();
		}
	}

