	public void InitDLCAILordVisibility()
	{
		for (int i = 0; i < 9; i++)
		{
			switch (i)
			{
			case 0:
			case 1:
				if (FrontendMenus.DLC1Owned)
				{
					NewAILordVisible.Add((Visibility)1);
					NewAILordNotVisible.Add((Visibility)2);
				}
				else
				{
					NewAILordVisible.Add((Visibility)2);
					NewAILordNotVisible.Add((Visibility)1);
				}
				break;
			case 2:
			case 3:
				if (FrontendMenus.DLC2Owned)
				{
					NewAILordVisible.Add((Visibility)1);
					NewAILordNotVisible.Add((Visibility)2);
				}
				else
				{
					NewAILordVisible.Add((Visibility)2);
					NewAILordNotVisible.Add((Visibility)1);
				}
				break;
			case 5:
			case 6:
				if (FrontendMenus.DLC3Owned)
				{
					NewAILordVisible.Add((Visibility)1);
					NewAILordNotVisible.Add((Visibility)2);
				}
				else
				{
					NewAILordVisible.Add((Visibility)2);
					NewAILordNotVisible.Add((Visibility)1);
				}
				break;
			default:
				NewAILordNotVisible.Add((Visibility)0);
				NewAILordVisible.Add((Visibility)0);
				break;
			}
		}
	}

