	public void InFoodReportShowEaten(int gameOverRide)
	{
		if (gameOverRide == 1)
		{
			for (int i = 0; i < 4; i++)
			{
				foodNotEdible[i] = GameData.Instance.lastGameState.food_types_not_eatable[i];
			}
		}
		((UIElement)HUDBuildingPanel.RefStopMeatConsumption).Visibility = (Visibility)1;
		((UIElement)HUDBuildingPanel.RefStopCheeseConsumption).Visibility = (Visibility)1;
		((UIElement)HUDBuildingPanel.RefStopBreadConsumption).Visibility = (Visibility)1;
		((UIElement)HUDBuildingPanel.RefStopApplesConsumption).Visibility = (Visibility)1;
		if (foodNotEdible[2] == 1)
		{
			((UIElement)HUDBuildingPanel.RefStopMeatConsumption).Visibility = (Visibility)2;
		}
		if (foodNotEdible[1] == 1)
		{
			((UIElement)HUDBuildingPanel.RefStopCheeseConsumption).Visibility = (Visibility)2;
		}
		if (foodNotEdible[0] == 1)
		{
			((UIElement)HUDBuildingPanel.RefStopBreadConsumption).Visibility = (Visibility)2;
		}
		if (foodNotEdible[3] == 1)
		{
			((UIElement)HUDBuildingPanel.RefStopApplesConsumption).Visibility = (Visibility)2;
		}
	}

