	public void ButtonCreateTroop(object parameter)
	{
		Enums.eChimps chimpEnum = getChimpEnum(parameter as string);
		bool flag = true;
		switch (chimpEnum)
		{
		case Enums.eChimps.CHIMP_TYPE_ARCHER:
			if (GameData.Instance.lastGameState.troop_types_available[0] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitArcherButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_SPEARMAN:
			if (GameData.Instance.lastGameState.troop_types_available[2] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitSpearmanButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_MACEMAN:
			if (GameData.Instance.lastGameState.troop_types_available[4] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitMacemanButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_SWORDSMAN:
			if (GameData.Instance.lastGameState.troop_types_available[5] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitSwordsmanButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_XBOWMAN:
			if (GameData.Instance.lastGameState.troop_types_available[1] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitXBowmanButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_PIKEMAN:
			if (GameData.Instance.lastGameState.troop_types_available[3] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitPikemanButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_KNIGHT:
			if (GameData.Instance.lastGameState.troop_types_available[6] <= 0 && ((UIElement)HUDBuildingPanel.RefRecruitKnightButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_LADDERMAN:
			if (!((UIElement)HUDBuildingPanel.RefRecruitLaddermanButton).IsEnabled)
			{
				flag = false;
			}
			break;
		case Enums.eChimps.CHIMP_TYPE_ENGINEER:
			if (!((UIElement)HUDBuildingPanel.RefRecruitEngineerButton).IsEnabled)
			{
				flag = false;
			}
