	public void ButtonReports(object parameter)
	{
		int num = Convert.ToInt32(parameter as string);
		if (num == 0)
		{
			MainControls.instance.StopAllPlacement();
		}
		WasInGranary = false;
		if (FreezeMainControls)
		{
			if (GameData.Instance.app_mode == 16 && (GameData.Instance.app_sub_mode == 76 || GameData.Instance.app_sub_mode == 68 || GameData.Instance.app_sub_mode == 67 || GameData.Instance.app_sub_mode == 66))
			{
				EditorDirector.instance.directSetAppMode(14, 0);
				return;
			}
			EngineInterface.GameAction(Enums.GameActionCommand.CloseTroopsPanel, 0, 0);
			num = 9;
			PropEx.SetButtonVisibility((UIElement)(object)HUDBuildingPanel.RefButtonArmyReportBack, (Visibility)1);
			PropEx.SetButtonVisibility((UIElement)(object)HUDBuildingPanel.RefButtonArmyReportBack2, (Visibility)1);
			PropEx.SetButtonVisibility((UIElement)(object)HUDBuildingPanel.RefButtonArmyReportBack3, (Visibility)1);
		}
		else
		{
			PropEx.SetButtonVisibility((UIElement)(object)HUDBuildingPanel.RefButtonArmyReportBack, (Visibility)2);
			PropEx.SetButtonVisibility((UIElement)(object)HUDBuildingPanel.RefButtonArmyReportBack2, (Visibility)2);
			PropEx.SetButtonVisibility((UIElement)(object)HUDBuildingPanel.RefButtonArmyReportBack3, (Visibility)2);
			EngineInterface.GameAction(Enums.GameActionCommand.CloseTroopsPanel, 0, 0);
		}
		switch (num)
		{
		case 0:
			EditorDirector.instance.directSetAppMode(16, 71);
			break;
		case 1:
			EditorDirector.instance.directSetAppSubMode(72);
			break;
		case 2:
			EditorDirector.instance.directSetAppSubMode(73);
			break;
		case 3:
			EditorDirector.instance.directSetAppSubMode(74);
			break;
		case 4:
			EditorDirector.instance.directSetAppSubMode(75);
			break;
		case 5:
			EditorDirector.instance.directSetAppSubMode(76);
			break;
		case 6:
			EditorDirector.instance.directSetAppSubMode(77);
			break;
		case 7:
			EditorDirector.instance.directSetAppSubMode(78);
			break;
		case 8:
			EditorDirector.instance.directSetAppSubMode(79);
			break;
		case 9:
			EditorDirector.instance.directSetAppMode(16, 76);
			break;
		}
		if (num == 0)
		{
			InBuildingGameAction();
		}
		switch (num)
		{
		case 0:
			setUpInbuilding(71, 190);
			break;
		case 1:
			setUpInbuilding(0, 190);
			break;
		case 2:
			setUpInbuilding(0, 190);
			break;
		case 3:
			setUpInbuilding(0, 190);
			break;
		case 4:
			setUpInbuilding(0, 190);
			break;
		case 5:
			setUpInbuilding(0, 190);
			break;
		case 6:
			setUpInbuilding(0, 190);
			break;
		case 7:
			setUpInbuilding(0, 190);
			break;
		case 8:
			setUpInbuilding(0, 190);
			break;
		case 9:
			setUpInbuilding(76, 190);
			break;
		}
	}

	public void ButtonScribeMouseEnterFunction(object parameter)
