	public int[] updateSaveRadarTexture()
	{
		//IL_0086: Unknown result type (might be due to invalid IL or missing references)
		//IL_008c: Expected O, but got Unknown
		Show_Radar160Border = false;
		Show_Radar300Border = false;
		Show_Radar500Border = false;
		Show_Radar700Border = false;
		int world_size = 0;
		int[] keep_locations = null;
		byte[] saveRadar = EngineInterface.getSaveRadar(ref keep_locations, ref world_size);
		if (saveRadar != null)
		{
			switch (world_size)
			{
			case 160:
				Show_Radar160Border = true;
				break;
			case 300:
				Show_Radar300Border = true;
				break;
			case 500:
				Show_Radar500Border = true;
				break;
			case 700:
				Show_Radar700Border = true;
				break;
			}
			TextureSource radarRequesterImage = new TextureSource(MapFileManager.Instance.GetRadarPreview(saveRadar));
			Instance.RadarRequesterImage = (ImageSource)(object)radarRequesterImage;
			return keep_locations;
		}
		Instance.RadarRequesterImage = null;
		return null;
	}

