	}

	public void ButtonBriefingQuit(object parameter)
	{
		MyAudioManager.Instance.StopSpeech(3);
		if (!BriefingFromStory)
		{
			SFXManager.instance.playSpeech(1, "General_Quitgame.wav", 1f, ignoreSpeechMuting: false, ignorePauseState: true);
			HUD_ConfirmationPopup.ShowConfirmation(Translate.Instance.lookUpText(Enums.eTextSections.TEXT_GAME_OPTIONS, 7), delegate
			{
				HUDBriefingPanel.CloseHelp();
				InitNewScene(Enums.SceneIDS.FrontEnd);
			}, delegate
			{
				_ = BriefingMode;
				_ = 3;
			});
			return;
		}
		HUDBriefingPanel.CloseHelp();
		InitNewScene(Enums.SceneIDS.FrontEnd);
		if (GameData.Instance.game_type == 0)
		{
			switch (GameData.Instance.mission_level)
			{
			case 1:
			case 2:
			case 3:
			case 4:
			case 5:
				FrontEndMenu.ButtonClicked("Historical1");
				break;
			case 6:
			case 7:
			case 8:
			case 9:
			case 10:
				FrontEndMenu.ButtonClicked("Historical2");
				break;
			case 11:
			case 12:
			case 13:
			case 14:
			case 15:
				FrontEndMenu.ButtonClicked("Historical3");
				break;
			case 16:
			case 17:
			case 18:
			case 19:
			case 20:
				FrontEndMenu.ButtonClicked("Historical4");
				break;
			case 21:
			case 22:
			case 23:
			case 24:
			case 25:
				FrontEndMenu.ButtonClicked("Historical5");
				break;
			case 26:
			case 27:
			case 28:
			case 29:
			case 30:
				FrontEndMenu.ButtonClicked("Historical6");
				break;
			case 31:
			case 32:
			case 33:
			case 34:
			case 35:
				FrontEndMenu.ButtonClicked("Historical7");
				break;
			}
			return;
		}
		if (Director.instance.WasSkirmishModeGame)
		{
			if (GameData.Instance.SkirmishGameType == 1)
			{
				switch (GameData.Instance.SkirmishTrailType)
				{
				case 0:
					FrontEndMenu.ButtonClicked("Trail");
					break;
				case 1:
					FrontEndMenu.ButtonClicked("Trail2");
					break;
				case 2:
					FrontEndMenu.ButtonClicked("Trail3");
					break;
				case 11:
					FrontEndMenu.ButtonClicked("Sands1");
					break;
				case 12:
					FrontEndMenu.ButtonClicked("Sands2");
					break;
				case 13:
					FrontEndMenu.ButtonClicked("Sands3");
					break;
				case 14:
					FrontEndMenu.ButtonClicked("Sands4");
					break;
				case 15:
					FrontEndMenu.ButtonClicked("Sands5");
					break;
				case 16:
					FrontEndMenu.ButtonClicked("Sands6");
					break;
				case 17:
					FrontEndMenu.ButtonClicked("Sands7");
					break;
				case 3:
				case 4:
				case 5:
				case 6:
				case 7:
				case 8:
				case 9:
				case 10:
					break;
				}
			}
			else if (GameData.Instance.SkirmishGameType == 2)
			{
				if (Instance.HUDIngameMenu.restartSkirmishMapInfo != null)
				{
					Instance.FrontEndMenu.OpenCustomTrail(Instance.HUDIngameMenu.restartSkirmishMapInfo.customTrailName, Instance.HUDIngameMenu.restartSkirmishMapInfo.customTrailLevel);
				}
			}
			else
			{
				if (HUDIngameMenu.restartSkirmishMapInfo != null)
				{
					FRONT_Multiplayer.Open(skirmishSetup: true, HUDIngameMenu.restartSkirmishMapInfo, coopSetup: false, HUDIngameMenu.restartSkirmishMapInfo.customTestMission);
				}
				else
				{
					FRONT_Multiplayer.Open(skirmishSetup: true, HUDIngameMenu.restartSkirmishMapInfo);
				}
				HUDIngameMenu.restartSkirmishMapInfo = null;
				Show_FrontMenus_Background_Main = false;
				Show_Frontend_MainMenu = false;
			}
			return;
		}
		FrontendMenus.ClearUIPanels();
		if (GameData.Instance.game_type == 2)
		{
			switch (GameData.Instance.mapType)
			{
			case Enums.GameModes.INVASION:
				FRONT_StandaloneMission.Open(Enums.StartUpUIPanels.Invasion);
				Show_FrontMenus_Background_Main = false;
				Show_Frontend_MainMenu = false;
				break;
			case Enums.GameModes.BUILD:
				FRONT_StandaloneMission.Open(Enums.StartUpUIPanels.FreeBuild);
				Show_FrontMenus_Background_Main = false;
				Show_Frontend_MainMenu = false;
				break;
			}
		}
	}

	public void ButtonBriefingResume(object parameter)
	{
		ButtonBriefingResume(parameter, fromEscape: false);
	}

	public void ButtonBriefingResume(object parameter, bool fromEscape)
	{
		if (fromEscape && BriefingFromStory)
		{
			ButtonBriefingQuit(0);
			return;
		}
		MyAudioManager.Instance.StopSpeech(3);
		if (OST_Starting_goods_Vis && BriefingFromStory)
		{
			OnScreenText.Instance.startCart();
		}
		if (BriefingFromStory && GameData.Instance.game_type == 0 && GameData.Instance.difficulty_level != Enums.GameDifficulty.DIFFICULTY_NORMAL && GameData.Instance.difficulty_level != Enums.GameDifficulty.DIFFICULTY_NA)
		{
			EditorDirector.instance.stopGameSim();
			EditorDirector.instance.LoadCampaignMap(startedMission, (int)GameData.Instance.difficulty_level);
		}
		FatControler.instance.RadarMouseClickDelayPostBriefing();
		if (!BriefingFromStory && GameData.Instance.lastGameState != null && GameData.Instance.lastGameState.app_sub_mode != 49 && GameData.Instance.lastGameState.app_sub_mode != 13)
		{
			EditorDirector.instance.directSetAppMode(14, 0);
		}
		EngineInterface.GameAction(Enums.GameActionCommand.HideObjectiveProgress, 0, 0);
		Show_HUD_Main = true;
		RollOverText_Margin = "0,0,-20,130";
		Show_HUD_Troops = false;
		Show_HUD_Building = false;
		Show_HUD_Briefing = false;
		Show_HUD_MissionOver = false;
		Show_HUD_Book = true;
		IsMapEditorMode = false;
		MyAudioManager.Instance.PauseSpeech(state: false);
		if (BriefingFromStory)
		{
			EngineInterface.GameAction(Enums.GameActionCommand.ResetTime, 0, 0);
		}
		if (!preBriefingWasPaused && !Director.instance.MultiplayerGame)
		{
			Director.instance.SetPausedState(state: false);
		}
		((UIElement)HUDRoot.RefRadarMapGrid).Visibility = (Visibility)2;
		((UIElement)HUDRoot.RefReportsControlGrid).Visibility = (Visibility)2;
		HUDBriefingPanel.CloseHelp();
		BriefingFromStory = false;
		FatControler.MouseIsDownStroke = false;
		FatControler.MouseIsUpStroke = false;
	}

	public void ButtonBriefingMode(object parameter)
	{
		int num = Convert.ToInt32(parameter as string);
		if (num == 3 && ConfigSettings.Settings_UseSteamOverlayForHelp)
		{
			HUDBriefingPanel.OpenHelpInOverlay();
			return;
		}
		int briefingMode = BriefingMode;
		BriefingMode = num;
		FatControler.instance.BriefingUIUpdate();
		((UIElement)HUDBriefingPanel.RefObjectivesSubPanel).Visibility = (Visibility)1;
		((UIElement)HUDBriefingPanel.RefHintsSubPanel).Visibility = (Visibility)1;
		((UIElement)HUDBriefingPanel.RefHelpSubPanel).Visibility = (Visibility)1;
		if (BriefingMode == 1)
		{
			((UIElement)HUDBriefingPanel.RefObjectivesSubPanel).Visibility = (Visibility)2;
		}
		else if (BriefingMode == 2)
		{
			((UIElement)HUDBriefingPanel.RefHintsSubPanel).Visibility = (Visibility)2;
		}
		else if (BriefingMode == 3)
		{
			((UIElement)HUDBriefingPanel.RefHelpSubPanel).Visibility = (Visibility)2;
		}
		if (briefingMode != num)
		{
			_ = BriefingMode;
			_ = 3;
		}
	}

	public void ButtonBriefingDifficulty(object parameter)
	{
		Enums.GameDifficulty gameDifficulty = GameData.Instance.difficulty_level;
		switch (gameDifficulty)
		{
		case Enums.GameDifficulty.DIFFICULTY_EASY:
			gameDifficulty = Enums.GameDifficulty.DIFFICULTY_NORMAL;
			break;
		case Enums.GameDifficulty.DIFFICULTY_NA:
		case Enums.GameDifficulty.DIFFICULTY_NORMAL:
			gameDifficulty = Enums.GameDifficulty.DIFFICULTY_HARD;
			break;
		case Enums.GameDifficulty.DIFFICULTY_HARD:
			gameDifficulty = Enums.GameDifficulty.DIFFICULTY_VERYHARD;
			break;
		case Enums.GameDifficulty.DIFFICULTY_VERYHARD:
			gameDifficulty = Enums.GameDifficulty.DIFFICULTY_EASY;
			break;
		}
		EngineInterface.setEcoCampaignDifficulty(gameDifficulty);
		GameData.Instance.difficulty_level = gameDifficulty;
	}

