	public void ButtonExtendedFeaturesFunction(object parameter)
	{
		//IL_00d0: Unknown result type (might be due to invalid IL or missing references)
		//IL_00d6: Invalid comparison between Unknown and I4
		switch ((string)parameter)
		{
		case "Objectives":
			SetGoodsPopupState(visible: false);
			SetObjectivePopupState(!Show_HUD_Objectives);
			SetHUDGoodsVisible(allVis: true);
			return;
		case "Goods":
			SetObjectivePopupState(visible: false);
			SetGoodsPopupState(!Show_HUD_Goods);
			SetHUDGoodsVisible(ShowAllHudVis);
			return;
		case "Freebuild":
			HUD_FreebuildMenu.ToggleMenu();
			return;
		case "Trading":
			SetHUDGoodsVisible(!ShowAllHudVis);
			return;
		}
		try
		{
			int num = int.Parse((string)parameter);
			previousTradePanel = -10;
			if (GameData.Instance.app_mode == 16 && GameData.Instance.app_sub_mode == 57 && (int)((UIElement)HUDBuildingPanel.RefTradePost_Trade_Auto).Visibility == 2)
			{
				EngineInterface.GameAction(Enums.GameActionCommand.SelectBuildingType, 26, num);
				EngineInterface.GameAction(Enums.GameActionCommand.Autotrade_Apply, 0, 0);
				HUDBuildingPanel.initAutoTrade(num);
			}
			else
			{
				EngineInterface.GameAction(Enums.GameActionCommand.SelectBuildingType, 26, num);
			}
		}
		catch (Exception)
		{
		}
	}

	public void SetHUDGoodsVisible(bool allVis)
	{
		ShowAllHudVis = allVis;
		if (allVis)
		{
			for (int i = 0; i < 25; i++)
			{
				DisplayHudGoodsBool[i] = true;
				DisplayHudGoodsNotTradeableBool[i] = !AllStoredGoodsVisible[i];
			}
		}
		else
		{
			for (int j = 0; j < 25; j++)
			{
				DisplayHudGoodsBool[j] = AllStoredGoodsVisible[j];
				DisplayHudGoodsNotTradeableBool[j] = false;
			}
		}
		if (GameData.Instance.lastGameState != null && (GameData.Instance.lastGameState.gotMarket & 1) != 0)
		{
			Show_HUD_Goods_Normal = false;
			Show_HUD_Goods_Trade = true;
			for (int k = 0; k < 25; k++)
			{
				DisplayHudGoodsTradeableBool[k] = AllStoredGoodsVisible[k];
			}
			return;
		}
		Show_HUD_Goods_Normal = true;
		Show_HUD_Goods_Trade = false;
		for (int l = 0; l < 25; l++)
		{
			DisplayHudGoodsTradeableBool[l] = false;
			if (allVis)
			{
				DisplayHudGoodsNotTradeableBool[l] = true;
			}
		}
	}

