	public void SetVisibleState(bool state)
	{
		if (!state)
		{
			Show_InGameUI = false;
			UIVisible = false;
			Compass_Vis = false;
			Instance.ShowGameTime = (Visibility)0;
			ShowLocalTime = (Visibility)0;
			Show_HUD_Extreme = false;
			return;
		}
		UIVisible = true;
		Show_InGameUI = true;
		Compass_Vis = ConfigSettings.Settings_Compass || Instance.IsMapEditorMode;
		if (ConfigSettings.Settings_ShowGameTime && !Instance.IsMapEditorMode)
		{
			ShowGameTime = (Visibility)2;
		}
		else
		{
			ShowGameTime = (Visibility)0;
		}
		if (ConfigSettings.Settings_ShowLocalTime)
		{
			ShowLocalTime = (Visibility)2;
		}
		else
		{
			ShowLocalTime = (Visibility)0;
		}
	}

