	public TextureSource LoadImageFile(byte[] fileData)
	{
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		//IL_000b: Expected O, but got Unknown
		//IL_008a: Unknown result type (might be due to invalid IL or missing references)
		//IL_0090: Expected O, but got Unknown
		try
		{
			Texture2D val = new Texture2D(2, 2, (TextureFormat)4, false, true);
			ImageConversion.LoadImage(val, fileData);
			Color[] pixels = val.GetPixels();
			for (int i = 0; i < pixels.Length; i++)
			{
				pixels[i].r *= pixels[i].a;
				pixels[i].g *= pixels[i].a;
				pixels[i].b *= pixels[i].a;
			}
			val.SetPixels(pixels);
			val.Apply();
			TextureSource result = new TextureSource(val);
			Object.DestroyImmediate((Object)(object)val);
			return result;
		}
		catch (Exception)
		{
			return null;
		}
	}

