		HUDFreebuildMenu.ButtonClicked(param);
	}

	public void OptionsFunction(object parameter)
	{
		int param = Convert.ToInt32(parameter as string);
		HUDOptions.ButtonClicked(param);
	}

	public void CoAFunction(object parameter)
	{
		HUD_CoatOfArms.ButtonClicked(parameter as string);
	}

	public void StartCampaignMission(int StoryChapter)
	{
		Show_BlackOut = true;
		InitNewScene(Enums.SceneIDS.MainGame);
		Instance.HUDIngameMenu.restartMapInfo = null;
		Instance.HUDIngameMenu.restartSkirmishMapInfo = null;
		Instance.HUDIngameMenu.restartMPInfo = null;
		startedMission = StoryChapter;
		EditorDirector.instance.LoadCampaignMap(StoryChapter, 1);
		EngineInterface.GameAction(Enums.GameActionCommand.HideObjectiveProgress, 1, 1);
		Director.instance.SetPostUpdateCallback(delegate
		{
			FatControler.instance.BriefingUIUpdate();
			ButtonGotoBriefing("FromStory");
			InitObjectiveGoodsPanel();
			Show_BlackOut = false;
		});
	}

	public void StartSkirmishTrailMission(int trailType, int trailID, int difficulty)
	{
		Show_BlackOut = true;
		InitNewScene(Enums.SceneIDS.MainGame);
		Instance.HUDIngameMenu.restartMapInfo = null;
		Instance.HUDIngameMenu.restartSkirmishMapInfo = null;
		Instance.HUDIngameMenu.restartMPInfo = null;
		EditorDirector.instance.LoadSkirmishMap(trailType, trailID, difficulty);
		EngineInterface.GameAction(Enums.GameActionCommand.HideObjectiveProgress, 1, 1);
		Director.instance.SetPostUpdateCallback(delegate
		{
			FatControler.instance.BriefingUIUpdate();
			ButtonGotoBriefing("FromStory");
			InitObjectiveGoodsPanel();
			Show_BlackOut = false;
		});
	}

	public void StartCustomTrailMission(string CustomTrailName, int missionID, int difficulty)
	{
		Show_BlackOut = true;
		InitNewScene(Enums.SceneIDS.MainGame);
		Instance.HUDIngameMenu.restartMapInfo = null;
		Instance.HUDIngameMenu.restartSkirmishMapInfo = null;
		Instance.HUDIngameMenu.restartMPInfo = null;
		if (EditorDirector.instance.LoadCustomTrailMap(CustomTrailName, missionID, difficulty))
		{
			EngineInterface.GameAction(Enums.GameActionCommand.HideObjectiveProgress, 1, 1);
			Director.instance.SetPostUpdateCallback(delegate
			{
				FatControler.instance.BriefingUIUpdate();
				ButtonGotoBriefing("FromStory");
				InitObjectiveGoodsPanel();
				Show_BlackOut = false;
			});
		}
		else
		{
			Show_BlackOut = false;
			InitNewScene(Enums.SceneIDS.FrontEnd);
		}
	}

	public void PreStartMapMission()
	{
		Show_BlackOut = true;
		InitNewScene(Enums.SceneIDS.MainGame);
	}

	public void PostStartMapMission()
	{
		Director.instance.SetPostUpdateCallback(delegate
		{
			FatControler.instance.BriefingUIUpdate();
			ButtonGotoBriefing("FromStory");
			InitObjectiveGoodsPanel();
			Show_BlackOut = false;
		});
	}

	public void SetLocalisedLayout(string locale)
	{
		if (locale == "jaJP")
		{
			ChimpNameTextFontSize = 22.0;
		}
	}

	public void SetNoesisKeyboardState(bool state)
	{
		FatControler.instance.SetNoesisKeyboardState(state);
	}

	public static DependencyObject GetScrollViewer(DependencyObject o)
	{
		if (o is ScrollViewer)
		{
			return o;
		}
		for (int i = 0; i < VisualTreeHelper.GetChildrenCount(o); i++)
		{
			DependencyObject scrollViewer = GetScrollViewer(VisualTreeHelper.GetChild(o, i));
			if (!((BaseComponent)(object)scrollViewer == (BaseComponent)null))
			{
				return scrollViewer;
			}
		}
		return null;
	}

	public static DependencyObject GetListBox(DependencyObject o)
	{
		if (o is ListBox)
		{
			return o;
		}
		for (int i = 0; i < VisualTreeHelper.GetChildrenCount(o); i++)
		{
			DependencyObject listBox = GetListBox(VisualTreeHelper.GetChild(o, i));
			if (!((BaseComponent)(object)listBox == (BaseComponent)null))
			{
				return listBox;
			}
		}
		return null;
	}

	public static void setupImages()
	{
		for (int i = 0; i < 108; i++)
		{
			GameImages.Add(null);
			GameImageData.Add(null);
		}
		Thread thread = new Thread(runImageLoading);
		thread.Name = "CrusaderDEImageLoading";
		thread.Start();
	}

	public static void runImageLoading()
	{
		int num = 0;
		string[] array = imageFileNames;
		foreach (string text in array)
		{
			if (text != null && text.Length > 0)
			{
				try
				{
					GameImageData[num] = File.ReadAllBytes(text);
				}
				catch (Exception)
				{
				}
			}
			num++;
		}
	}

	public ImageSource GetImage(Enums.eImages imageID)
	{
		if ((int)imageID >= GameImages.Count)
		{
			return null;
		}
		if (GameImages[(int)imageID] == null)
		{
			if (imageFileNames[(int)imageID] != "")
			{
				GameImages[(int)imageID] = new AnImage
				{
					_image = LoadImageFile(GameImageData[(int)imageID])
				};
				GameImageData[(int)imageID] = null;
				return (ImageSource)(object)GameImages[(int)imageID].Image;
			}
			return null;
		}
		return (ImageSource)(object)GameImages[(int)imageID].Image;
	}

