	public void SetSpriteWidth1(int thisSprite, int scale)
	{
		SpriteWidth1 = GameSpriteDims[thisSprite, 0] * scale / 100;
		SpriteHeight1 = GameSpriteDims[thisSprite, 1] * scale / 100;
	}

