	public ImageSource getAIFace(int ai, bool allowExtendedRemapping = false)
	{
		if (allowExtendedRemapping && ai >= 30 && ai <= 37 && GameData.Instance.extendedLordMapping[ai - 30] > 0)
		{
			ai = GameData.Instance.extendedLordMapping[ai - 30];
		}
		switch (ai)
		{
		case 1:
			return GameSprites[372];
		case 2:
			return GameSprites[373];
		case 3:
			return GameSprites[374];
		case 4:
			return GameSprites[375];
		case 5:
			return GameSprites[376];
		case 6:
			return GameSprites[377];
		case 7:
			return GameSprites[378];
		case 8:
			return GameSprites[379];
		case 9:
			return GameSprites[380];
		case 10:
			return GameSprites[381];
		case 11:
			return GameSprites[382];
		case 12:
			return GameSprites[383];
		case 13:
			return GameSprites[384];
		case 14:
			return GameSprites[385];
		case 15:
			return GameSprites[386];
		case 16:
			return GameSprites[387];
		case 17:
			return GameSprites[577];
		case 18:
			return GameSprites[578];
		case 19:
			return GameSprites[579];
		case 20:
			return GameSprites[580];
		case 21:
			return GameSprites[581];
		case 22:
			return GameSprites[582];
		case 23:
			return GameSprites[583];
		case 24:
			return GameSprites[584];
		case 25:
			return GameSprites[585];
		case 26:
			return GameSprites[730];
		case 27:
			return GameSprites[731];
		case 30:
		case 31:
		case 32:
		case 33:
		case 34:
		case 35:
		case 36:
		case 37:
		{
			int num = 0;
			if (HUDIngameMenu.restartSkirmishMapInfo != null)
			{
				if (HUDIngameMenu.restartSkirmishMapInfo.aivs[ai - 30] != null && HUDIngameMenu.restartSkirmishMapInfo.aivs[ai - 30].lordConfig != null)
				{
					num = HUDIngameMenu.restartSkirmishMapInfo.aivs[ai - 30].lordConfig.lordData.lord_gfx_type;
				}
				if (HUDIngameMenu.restartSkirmishMapInfo.aivs[ai - 30].lordName.Length > 0)
				{
					ImageSource image = (ImageSource)(object)HUDIngameMenu.restartSkirmishMapInfo.aivs[ai - 30].image;
					if ((BaseComponent)(object)image != (BaseComponent)null)
					{
						return image;
					}
				}
			}
			else if (HUDIngameMenu.restartMPInfo != null)
			{
				num = HUDIngameMenu.restartMPInfo.LordType[ai - 30];
				ImageSource val = (ImageSource)(object)HUDIngameMenu.restartMPInfo.images[ai - 30];
				if ((BaseComponent)(object)val != (BaseComponent)null)
				{
					return val;
				}
			}
			else if (Show_MultiplayerSetup && FRONTMultiplayer.AIVs[ai - 30] != null && FRONTMultiplayer.AIVs[ai - 30].lordConfig != null)
			{
				num = FRONTMultiplayer.AIVs[ai - 30].lordConfig.lordData.lord_gfx_type;
				ImageSource customLordImage = (ImageSource)(object)CustomisationFileManager.Instance.GetCustomLordImage(FRONTMultiplayer.AIVs[ai - 30].lordName);
				if ((BaseComponent)(object)customLordImage != (BaseComponent)null)
				{
					return customLordImage;
				}
			}
			return (ImageSource)(num switch
			{
				1 => GameSprites[739], 
				2 => GameSprites[740], 
				3 => GameSprites[741], 
				4 => GameSprites[742], 
				5 => GameSprites[743], 
				6 => GameSprites[744], 
				7 => GameSprites[745], 
				_ => GameSprites[738], 
			});
		}
		default:
			return null;
		}
	}

